def count_Substring_With_Equal_Ends(s):
    """Write a python function to count the number of substrings with same first and last characters."""
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    return sum(n * (n + 1) // 2 for n in counts.values())
